-- Página JUNO Media, versión 4 (2026-10-26): diseño propio con el bloque «colaboracion» (migración
-- 20261026040000_bloque_colaboracion.sql, que tiene que ir antes). 0 apertura, 1 lo que nos une, 2 para tu proyecto,
-- 3 proyectos hechos juntos, 4 la productora, 5 llamada. Actualiza los seis bloques que ya existen; no borra nada.
begin;

update public.bloques set tipo = 'colaboracion'::public.tipo_bloque, datos = $json${"parte": "apertura", "titulo": "Un filmmaker y una productora, *en sinergia*", "texto": "JUNO Media es una productora audiovisual y cinematográfica con la que comparto buena parte de mis proyectos. Trabajamos codo con codo, con la misma exigencia y el mismo cuidado en cada encargo.", "imagenes": [{"medio": "d8248ed7-bb85-48e0-8559-4a9779e5deb8", "pie": ""}, {"medio": "dd1964cd-fa6b-4a57-ae39-635aa3913627", "pie": ""}, {"medio": "508f8ec8-b800-45cd-bf9a-013f1b276ef9", "pie": ""}]}$json$::jsonb where pagina_id = (select id from public.paginas where slug = 'juno-media' and idioma = 'es') and orden = 0;

update public.bloques set tipo = 'colaboracion'::public.tipo_bloque, datos = $json${"parte": "relacion", "antetitulo": "La relación", "titulo": "Lo que nos *une*", "facetas": [{"titulo": "Profesional", "texto": "Los proyectos que entran en JUNO Media los sacamos adelante Noelia Fluxà y yo. Conocemos el método y los tiempos del otro, y eso se nota en cada rodaje y en cada entrega.", "imagen": "159ea3fd-69c6-4488-8eb5-4123af1427e4"}, {"titulo": "Artística", "texto": "Compartimos criterio sobre la luz, el encuadre y el ritmo. Las ideas se discuten, se afinan y llegan más lejos que si las trabajáramos por separado.", "imagen": "d8928679-31cd-4d4c-b336-6e1f03831034"}, {"titulo": "Personal", "texto": "Detrás hay confianza y muchas horas de rodaje juntos. JUNO Media cuida la cercanía con cada cliente, y esa misma cercanía es la que hay entre nosotros.", "imagen": "86267c64-9c4f-462e-ba39-f8178dfabf8b"}]}$json$::jsonb where pagina_id = (select id from public.paginas where slug = 'juno-media' and idioma = 'es') and orden = 1;

update public.bloques set tipo = 'colaboracion'::public.tipo_bloque, datos = $json${"parte": "valor", "antetitulo": "Para tu proyecto", "titulo": "Cuando el proyecto pide *una productora*", "texto": "Hay proyectos que necesitan algo más que una cámara: más equipo, más medios y una producción que lo sostenga todo de principio a fin. En esos casos, JUNO Media se encarga de la producción y tu proyecto queda en manos de un equipo que ya ha rodado junto muchas veces.", "imagen": "578294b5-732e-47ba-b6e9-26a2a015b2fd", "opciones": [{"titulo": "Si lo eliges tú", "texto": "Desde la primera conversación puedes pedir que tu proyecto se haga con JUNO Media."}, {"titulo": "Si te lo propongo yo", "texto": "Si veo que tu proyecto necesita las manos de una productora, te lo planteo antes de empezar."}]}$json$::jsonb where pagina_id = (select id from public.paginas where slug = 'juno-media' and idioma = 'es') and orden = 2;

update public.bloques set tipo = 'trabajos'::public.tipo_bloque, datos = $json${"antetitulo": "Hecho con JUNO Media", "titulo": "Lo que hemos hecho *juntos*", "origen": "juno"}$json$::jsonb where pagina_id = (select id from public.paginas where slug = 'juno-media' and idioma = 'es') and orden = 3;

update public.bloques set tipo = 'colaboracion'::public.tipo_bloque, datos = $json${"parte": "productora", "antetitulo": "La productora", "lema": "Expande tus alas", "texto": "Productora audiovisual y cinematográfica que trabaja cada proyecto a medida, con el máximo nivel de exigencia y de calidad. Publicidad, videoclips, conciertos y contenido para marcas, siempre al servicio de la esencia de cada cliente.", "enlace": {"texto": "Visitar junomedia.es", "href": "https://junomedia.es"}, "rotulo": "Marcas y artistas con los que hemos trabajado juntos"}$json$::jsonb where pagina_id = (select id from public.paginas where slug = 'juno-media' and idioma = 'es') and orden = 4;

update public.bloques set datos = datos || $json${"titulo": "¿Hablamos de tu *proyecto*?", "texto": "Cuéntame qué tienes en mente. Lo pensamos juntos y, si lo pide, lo hacemos con JUNO Media."}$json$::jsonb where pagina_id = (select id from public.paginas where slug = 'juno-media' and idioma = 'es') and orden = 5;

update public.paginas set seo_descripcion = $t$Josep Mira Lozano y JUNO Media, productora audiovisual y cinematográfica: una colaboración profesional, artística y personal, y lo que aporta a tu proyecto.$t$ where slug = 'juno-media' and idioma = 'es';

commit;
